# --- the cases, shared verbatim with `gold417.py` (which ran them on the baseline) ------------------------------------
# A case lays out one test-owned provision tree -- the generated config (TMP/provision/p417.json) and its layout template --
# and a synthetic project config pointing at it. The template check, the layout payloads, the no-follow read and the
# atomic writer are the launcher's own, run inside the tree; the board root, the durable session directory, the
# user-runtime check and the shared pane launcher stand in (they read the host and its accounts); the owner step is a
# recorder that may be told to fail; the runner refuses. Every call is recorded, and every file in the tree afterwards.
_REAL_RUN = subprocess.run
ROLES2 = [{"role": "director"}, {"role": "worker"}]
ROLES7 = [{"role": f"r{i}"} for i in range(7)]     # at seven roles every known legacy shape differs from the current one
LEGACY = [1, 2, 3, 4]      # indexes into the known generated shapes (0 is the current one)
BASIC = {"roles": ROLES2, "layout": "current"}
LAYOUT = {
    "hand-maintained: a layout outside the provision directory": {**BASIC, "layout_path": "custom/{LAYOUT}"},
    "hand-maintained: another name in the provision directory": {**BASIC, "layout_path": "provision/other-layout.json"},
    "hand-maintained: a config outside a provision directory": {**BASIC, "config_dir": "elsewhere", "layout_path": "elsewhere/{LAYOUT}"},
    "already current": BASIC,
    **{f"legacy shape {i}": {"roles": ROLES7, "layout": ("known", i)} for i in LEGACY},
    **{f"legacy shape {i}, dry run": {"roles": ROLES7, "layout": ("known", i), "dry_run": True} for i in LEGACY},
    "one role: every known shape is the current one": {"roles": [{"role": "director"}], "layout": ("known", 1)},
    "legacy, four roles (a grid)": {"roles": [{"role": f"r{i}"} for i in range(4)], "layout": ("known", 2)},
    "two roles, the one shape that differs": {"roles": ROLES2, "layout": ("known", 1)},
    "detached roles are not counted": {"roles": [*ROLES2, {"role": "d1", "detached": True}, {"role": "d2", "detached": True}], "layout": "current"},
    "detached roles are not counted, legacy": {"roles": [*ROLES2, {"role": "d1", "detached": True}], "layout": ("known", 1)},
    "an unknown shape, nothing else": {**BASIC, "layout": {"Orientation": 1, "Widgets": []}},
    "an unknown shape beside a pane launcher change": {**BASIC, "layout": {"Orientation": 1}, "pane_launcher": "old/team-launcher"},
    "a layout for another role count": {"roles": ROLES2, "layout": ("known-for", 5, 0)},
    "malformed JSON": {**BASIC, "layout": "{not json"},
    "empty file": {**BASIC, "layout": ""},
    "not UTF-8": {**BASIC, "layout": b'{"Orientation": "\xff"}'},
    "the current payload rebound on the launcher, keys unsorted": {"roles": ROLES7, "layout": ("known", 1), "current_payload": {"Widgets": [{"b": 1, "a": 2}], "Orientation": 2}},
    "missing": {**BASIC, "layout": None},
    "a directory in its place": {**BASIC, "layout": "DIR"},
}
