FUNCTIONS = ("_generated_project_durable_session_dir", "upgrade_generated_project_config", "upgrade_generated_project_layout")


def run_case(t: object, holder: object, spec: dict, reached: set) -> dict:
    """One case against `holder`'s function, in a fresh test-owned tree; the launcher's seams are recorded (or stand in) on `t`."""
    import dataclasses, shutil, tempfile
    from types import SimpleNamespace
    calls: list = []
    old_umask = os.umask(0o022)
    tmp = Path(tempfile.mkdtemp(prefix="syrd417-")).resolve()
    os.chmod(tmp, 0o755)

    def norm(value):
        if isinstance(value, (list, tuple)):
            return [norm(v) for v in value]
        if isinstance(value, dict):
            return {str(k): norm(v) for k, v in sorted(value.items())}
        if dataclasses.is_dataclass(value) and not isinstance(value, type):
            return {"dataclass": type(value).__name__, **{f.name: norm(getattr(value, f.name)) for f in dataclasses.fields(value)}}
        if isinstance(value, SimpleNamespace):
            return "CONFIG"
        if isinstance(value, Path):
            return "PATH " + norm(str(value))
        if isinstance(value, str):
            return value.replace(str(tmp), "TMP")
        if callable(value):
            return "subprocess.run" if value is _REAL_RUN else "THE RUNNER" if value is refusing_runner else "ANOTHER CALLABLE"
        return value

    def refusing_runner(*a, **k):
        raise AssertionError(f"the runner was called: {a} {k}")

    def record(name, fn):
        def call(*args, **kwargs):
            reached.add(name)
            try:
                answer = fn(*args, **kwargs)
            except BaseException as exc:
                calls.append([name, norm(list(args)), norm(dict(sorted(kwargs.items()))), {"raised": type(exc).__name__, "message": norm(str(exc))}])
                raise
            calls.append([name, norm(list(args)), norm(dict(sorted(kwargs.items()))), norm(answer)])
            return answer
        return call

    names = [*FUNCTIONS, "_is_generated_project_layout_template", "_new_project_layout_payload", "_known_generated_project_layout_payloads",
             "read_tenant_document_no_follow", "_write_json_atomic", "ensure_owner_file", "_tenant_board_root_from_config_or_plan",
             "_new_project_session_dir", "session_dir_uses_user_runtime", "switchyard_shared_pane_launcher"]
    saved = {n: getattr(t, n) for n in names}
    try:
        roles = [SimpleNamespace(role=r["role"], detached=r.get("detached", False),
                                 env={k: v.replace("{TMP}", str(tmp)) for k, v in r.get("env", {}).items()}) for r in spec["roles"]]
        config_dir = tmp / spec.get("config_dir", "provision")
        config_dir.mkdir(parents=True)
        config_path = config_dir / "p417.json"
        # The generated template's name, as the launcher's own presentation markers spell it.
        layout_name = t.presentation_layout_markers(SimpleNamespace(project="p417", project_name="", layout=None))[0]
        layout_path = tmp / spec.get("layout_path", "{DIR}/{LAYOUT}").replace("{DIR}", config_dir.name).replace("{LAYOUT}", layout_name)
        layout_path.parent.mkdir(parents=True, exist_ok=True)
        role_count = sum(1 for r in roles if not r.detached)
        layout = spec.get("layout")
        if layout == "current":
            layout_path.write_text(json.dumps(saved["_new_project_layout_payload"](role_count)), encoding="utf-8")
        elif isinstance(layout, tuple) and layout[0] == "known":
            layout_path.write_text(json.dumps(saved["_known_generated_project_layout_payloads"](role_count)[layout[1]]), encoding="utf-8")
        elif isinstance(layout, tuple) and layout[0] == "known-for":
            layout_path.write_text(json.dumps(saved["_known_generated_project_layout_payloads"](layout[1])[layout[2]]), encoding="utf-8")
        elif layout == "DIR":
            layout_path.mkdir()
        elif isinstance(layout, dict):
            layout_path.write_text(json.dumps(layout), encoding="utf-8")
        elif isinstance(layout, str):
            layout_path.write_text(layout, encoding="utf-8")
        elif isinstance(layout, bytes):
            layout_path.write_bytes(layout)
        raw_roles = spec.get("raw_roles", [{"role": r.role, "env": dict(r.env)} for r in roles])
        raw = {"project": "p417", "roles": raw_roles, "session_dir": "kept", "pane_launcher": "kept", "layout": str(layout_path)}
        target = tmp / spec["config_link"] if "config_link" in spec else config_path
        target.write_text(spec.get("raw_config_text", json.dumps(raw, indent=2, sort_keys=True)), encoding="utf-8")
        if "config_link" in spec:
            os.symlink(target.name, config_path)
        if "hardlink" in spec:
            os.link(config_path, tmp / spec["hardlink"])
        for name, to in spec.get("links", {}).items():
            os.symlink(to, tmp / name)
        for relative, mode in spec.get("loosen", []):
            os.chmod(tmp / relative, mode)
        owner = spec.get("run_as_user", "syrd417-owner")
        pane = spec.get("pane_launcher", "opt/current/scripts/team-launcher")
        config = SimpleNamespace(project="p417", run_as_user=owner, roles=roles, layout=layout_path,
                                 pane_launcher=(tmp / pane) if pane else None, session_dir=tmp / spec.get("session_dir", "durable/syrd417-owner"))
        board = spec.get("board_root")
        under = {n: getattr(holder, n) for n in FUNCTIONS}

        def owner_step(config, path, *, runner):
            if spec.get("owner_fails") == ("layout" if path == layout_path else "config"):
                raise SystemExit(f"team-launcher: failed to assign generated file {path} to {config.run_as_user}: syrd417 chown refused")

        on_launcher = {n: record(n, saved[n]) for n in FUNCTIONS}
        on_launcher.update({
            "_is_generated_project_layout_template": record("_is_generated_project_layout_template", saved["_is_generated_project_layout_template"]),
            "_new_project_layout_payload": record("_new_project_layout_payload", (lambda n: dict(spec["current_payload"])) if "current_payload" in spec else saved["_new_project_layout_payload"]),
            "_known_generated_project_layout_payloads": record("_known_generated_project_layout_payloads", saved["_known_generated_project_layout_payloads"]),
            "read_tenant_document_no_follow": record("read_tenant_document_no_follow", saved["read_tenant_document_no_follow"]),
            "_write_json_atomic": record("_write_json_atomic", saved["_write_json_atomic"]),
            "ensure_owner_file": record("ensure_owner_file", owner_step),
            "_tenant_board_root_from_config_or_plan": record("_tenant_board_root_from_config_or_plan", lambda c, p=None: (tmp / board) if board else None),
            "_new_project_session_dir": record("_new_project_session_dir", lambda project, user: str(tmp / "durable" / user)),
            "session_dir_uses_user_runtime": record("session_dir_uses_user_runtime", lambda d, u: bool(spec.get("user_runtime", False))),
            "switchyard_shared_pane_launcher": record("switchyard_shared_pane_launcher", lambda root=None: tmp / "opt" / "current" / "scripts" / "team-launcher"),
        })
        for n, f in on_launcher.items():
            setattr(t, n, f)
        kwargs = {"config_path": config_path}
        if spec.get("dry_run"):
            kwargs["dry_run"] = True
        if spec.get("runner") != "default":
            kwargs["runner"] = refusing_runner
        try:
            if spec.get("call") == "durable":
                got = under["_generated_project_durable_session_dir"](config)
            elif spec.get("entry") == "layout":
                got = under["upgrade_generated_project_layout"](config, **kwargs)
            else:
                got = under["upgrade_generated_project_config"](config, **kwargs)
            answer = norm(got)
        except AssertionError:
            raise
        except BaseException as exc:  # noqa: BLE001 -- the baseline's own answer, whatever it raises
            answer = {"raised": type(exc).__name__, "message": norm(str(exc))}
        for relative, mode in spec.get("loosen", []):
            os.chmod(tmp / relative, 0o755)
        files = {}
        for p in sorted(tmp.rglob("*")):
            rel = str(p.relative_to(tmp))
            if p.is_symlink():
                files[rel] = "SYMLINK -> " + os.readlink(p)
            elif p.is_file():
                files[rel] = norm(p.read_text(encoding="utf-8", errors="replace"))
        return {"answer": answer, "calls": calls, "files": files}
    finally:
        for n, f in saved.items():
            setattr(t, n, f)
        os.umask(old_umask)
        shutil.rmtree(tmp)
