def test_the_module_loads_no_other_switchyard_module_at_import() -> None:
    result = python("import sys, scripts.generated_layout_upgrade as m; "
                    "print(sorted(n for n in sys.modules if n.startswith('scripts.') and n != m.__name__))")
    check(result.returncode == 0 and result.stdout.strip() == "[]",
          f"it imports on its own, loading no other Switchyard module and never the launcher: {result.stdout}{result.stderr[-400:]}")


def test_either_import_order_gives_one_set_of_objects_and_the_defaults() -> None:
    for order in (("scripts.generated_layout_upgrade", "scripts.team_launcher"), ("scripts.team_launcher", "scripts.generated_layout_upgrade")):
        result = python("import importlib, inspect, subprocess; "
                        f"[importlib.import_module(n) for n in {order!r}]; "
                        "import scripts.team_launcher as t, scripts.generated_layout_upgrade as m; "
                        "d = lambda f, n: inspect.signature(f).parameters[n].default; "
                        f"print(all(getattr(t, n) is getattr(m, n) for n in {MOVED!r}), "
                        "all(d(f, 'runner') is subprocess.run and d(f, 'dry_run') is False for f in (m.upgrade_generated_project_config, m.upgrade_generated_project_layout)), "
                        "not hasattr(m, 'launcher') and not hasattr(m, 'LauncherUpgradeResult') and not hasattr(m, 'ProjectConfig'))")
        check(result.stdout.strip() == "True True True", f"{' then '.join(order)}: {result.stdout}{result.stderr[-600:]}")
    check(m.json is json and m.subprocess is subprocess and m.Path is Path, "the standard-library names are the module's own")


def test_the_seams_read_through_the_launcher_and_nothing_bound() -> None:
    tree = ast.parse((ROOT / "scripts" / "generated_layout_upgrade.py").read_text(encoding="utf-8"))
    for name in FUNCTIONS:
        node = next(n for n in tree.body if getattr(n, "name", None) == name)
        through: dict[str, int] = {}
        for x in ast.walk(node):
            if isinstance(x, ast.Attribute) and isinstance(x.value, ast.Name) and x.value.id == "launcher":
                through[x.attr] = through.get(x.attr, 0) + 1
        expected = SEAMS.get(name, {})
        check(through == expected, f"{name}: each launcher name read through it exactly as often as before: {through}")
        imports = [ast.unparse(x) for x in ast.walk(node) if isinstance(x, (ast.Import, ast.ImportFrom))]
        first = 1 if ast.get_docstring(node) is not None else 0
        check(imports == ["from scripts import team_launcher as launcher"] and ast.unparse(node.body[first]) == imports[0],
              f"{name}: the launcher imported first thing, and nothing else: {imports}")
        skip = {id(y) for part in [node.returns, *(a.annotation for a in node.args.args + node.args.kwonlyargs), *[d for d in node.args.kw_defaults if d]]
                if part is not None for y in ast.walk(part)}
        bare = sorted({x.id for x in ast.walk(node) if isinstance(x, ast.Name) and isinstance(x.ctx, ast.Load) and x.id in expected and id(x) not in skip})
        check(bare == [], f"{name}: none of them read past it: {bare}")
    top = [ast.unparse(n) for n in tree.body if isinstance(n, (ast.Import, ast.ImportFrom))]
    tc = [ast.unparse(n) for n in tree.body if isinstance(n, ast.If)]
    check(top == ["from __future__ import annotations", "import json", "import subprocess", "from pathlib import Path",
                  "from typing import TYPE_CHECKING, Any, Callable"]
          and tc == ["if TYPE_CHECKING:\n    from scripts.team_launcher import LauncherUpgradeResult, ProjectConfig"],
          f"the standard library, and the annotation types under TYPE_CHECKING: {top} {tc}")
    names = [n.name for n in tree.body if isinstance(n, (ast.FunctionDef, ast.ClassDef, ast.Assign))]
    check(names == list(MOVED), f"the three in the launcher's order, and nothing else: {names}")


def test_the_launcher_reexports_the_three_and_its_readers_reach_them_there() -> None:
    tree = ast.parse((ROOT / "scripts" / "team_launcher.py").read_text(encoding="utf-8"))
    imports = [n for n in tree.body if isinstance(n, ast.ImportFrom) and n.module == "scripts.generated_layout_upgrade"]
    check(len(imports) == 1 and sorted(a.name for a in imports[0].names) == sorted(MOVED) and all(a.asname is None for a in imports[0].names),
          "one explicit import of exactly the three, unaliased")
    check(imports[0].lineno < min(n.lineno for n in tree.body if isinstance(n, (ast.FunctionDef, ast.ClassDef))),
          "at the top, above every definition that could read them")
    defined = {getattr(n, "name", None) for n in tree.body} | {x.id for n in tree.body if isinstance(n, ast.Assign) for x in n.targets if isinstance(x, ast.Name)}
    # A neighbour stays reachable on the launcher: defined there, or -- once a later slice moves it on -- re-exported there, unaliased.
    exported = {a.name for n in tree.body if isinstance(n, ast.ImportFrom) and (n.module or "").startswith("scripts.")
                for a in n.names if a.asname is None}
    check(not defined & set(MOVED) and {"_is_generated_project_layout_template", "PRIVILEGED_PROVISION_ROOT_ENV", "launch_project", "LauncherUpgradeResult",
                                        "_known_generated_project_layout_payloads", "_new_project_layout_payload", "_new_project_session_dir",
                                        "_tenant_board_root_from_config_or_plan", "_write_json_atomic", "ensure_owner_file", "read_tenant_document_no_follow",
                                        "session_dir_uses_user_runtime", "switchyard_shared_pane_launcher"} <= defined | exported,
          "the launcher defines none of them, and keeps its neighbours and every seam they read, its own or re-exported")
    uses: dict = {}
    for fn in launcher_with_launch_project().body:
        if isinstance(fn, (ast.FunctionDef, ast.ClassDef)):
            for x in ast.walk(fn):
                if isinstance(x, ast.Name) and x.id in MOVED:
                    uses.setdefault(fn.name, {}).setdefault(x.id, 0)
                    uses[fn.name][x.id] += 1
    check(uses == DISPATCH, f"launch_project calls the entry point by its launcher global, exactly as often as before: {uses}")
    loose = sorted({x.id for n in tree.body if not isinstance(n, (ast.FunctionDef, ast.ClassDef, ast.Import, ast.ImportFrom)) for x in ast.walk(n)
                    if isinstance(x, ast.Name) and x.id in MOVED})
    check(loose == [], f"and nothing at module level reads them: {loose}")
    for path, uses in READERS.items():
        source = ast.parse((ROOT / path).read_text(encoding="utf-8"))
        got = sorted(ast.unparse(x) for x in ast.walk(source) if (isinstance(x, ast.Attribute) and x.attr in MOVED) or (isinstance(x, ast.Name) and x.id in MOVED))
        check(got == uses, f"{path} still reads it through the launcher: {got}")


# --- behaviour -----------------------------------------------------------------------------------------------------


def test_every_answer_is_the_baselines() -> None:
    check(sorted(CASES) == sorted(GOLDEN), "every measured case is asserted, and nothing else")
    for label, spec in CASES.items():
        for holder in (m, t):
            got = run(holder, spec)
            check(got == GOLDEN[label], f"{label} ({holder.__name__}): the baseline's answer, every call in order: {got}")


def test_the_rules_hold_in_the_measured_record() -> None:
    def answer(label):
        return GOLDEN[label]["answer"]

    def called(label):
        return [c[0] for c in GOLDEN[label]["calls"]]

    writes = ("_write_json_atomic", "ensure_owner_file", "read_tenant_document_no_follow")
    hand = "layout: hand-maintained: a layout outside the provision directory"
    check(answer(hand)["changed"] is False and not set(writes) & set(called(hand)), "a hand-maintained layout is left alone")
    layout_file = lambda label: next(v for k, v in GOLDEN[label]["files"].items() if k.startswith("provision/p417-") and k.endswith("-layout.json"))
    unknown = "layout: an unknown shape, nothing else"
    check(answer(unknown)["changed"] is False and layout_file(unknown) == '{"Orientation": 1, "Widgets": []}',
          "an unknown shape is never overwritten")
    for i in (1, 2, 3, 4):
        dry, wet = GOLDEN[f"layout: legacy shape {i}, dry run"], GOLDEN[f"layout: legacy shape {i}"]
        check(dry["answer"]["changed"] is False and not set(writes) & set(c[0] for c in dry["calls"])
              and layout_file(f"layout: legacy shape {i}, dry run") != layout_file(f"layout: legacy shape {i}"),
              f"legacy shape {i}: upgraded, and a dry run leaves the template as it was")
    symlinked = "no-follow: the config is a symlink, after a legacy layout upgrade"
    check(called(symlinked)[-1] == "read_tenant_document_no_follow" and "_write_json_atomic" not in called(symlinked)
          and answer(symlinked)["message"].endswith("Nothing was changed."), "a linked config is refused before any write to it")
    # Measured on the baseline and kept as it is (an extraction does not change semantics): a dry run whose only change is a
    # stale directorctl pin still rewrites the config. Reported separately.
    check("_write_json_atomic" in called("pins: no role pinned, dry run") and answer("pins: no role pinned, dry run")["changed"] is False,
          "the baseline's dry run still writes a stale directorctl pin (reported, not changed here)")


def test_every_launcher_seam_is_reached() -> None:
    expected = {name for reads in SEAMS.values() for name in reads if callable(getattr(t, name, None)) and not isinstance(getattr(t, name), type)}
    check(expected <= REACHED, f"a recorder on the launcher reached every seam: missing {sorted(expected - REACHED)}")


STRUCTURE = ("test_the_module_loads_no_other_switchyard_module_at_import", "test_either_import_order_gives_one_set_of_objects_and_the_defaults",
             "test_the_seams_read_through_the_launcher_and_nothing_bound", "test_the_launcher_reexports_the_three_and_its_readers_reach_them_there")
LAST = ("test_every_launcher_seam_is_reached",)


def main() -> int:
    names = sorted(name for name, value in globals().items() if name.startswith("test_") and callable(value))
    for name in [*STRUCTURE, *(name for name in names if name not in STRUCTURE + LAST), *LAST]:
        globals()[name]()
    print(f"generated_layout_upgrade_boundary_test: {CHECKS} checks ok")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
